"""Exhaustive classification of server requests generated by Codex CLI 0.167.2."""
LEGACY_EXEC = 'execCommandApproval'
LEGACY_PATCH = 'applyPatchApproval'
BACKEND = {'item/tool/call', 'account/chatgptAuthTokens/refresh', 'attestation/generate'}
SERVER_REQUESTS = {
    'item/commandExecution/requestApproval', 'item/fileChange/requestApproval',
    'item/permissions/requestApproval', 'item/tool/requestUserInput',
    'mcpServer/elicitation/request', LEGACY_EXEC, LEGACY_PATCH,
} | BACKEND


def bound_params(method, params):
    if method in (LEGACY_EXEC, LEGACY_PATCH):
        return {**params, 'threadId': params.get('conversationId')}
    return params


def legacy_description(method, params):
    from .approval_requests import option, visible
    if method == LEGACY_EXEC:
        command = params.get('command')
        if (not isinstance(command, list) or not command
                or any(not isinstance(v, str) for v in command) or not isinstance(params.get('cwd'), str)):
            raise ValueError('旧版命令参数不完整')
        preview = '命令参数（JSON数组，保留参数边界）：\n' + visible(command)
        preview += '\n目录：' + visible(params['cwd'])
    elif method == LEGACY_PATCH:
        changes = params.get('fileChanges')
        if params.get('grantRoot'):
            raise ValueError('会话写入目录授权不能当作单次文件修改')
        if not isinstance(changes, dict) or not changes:
            raise ValueError('旧版文件修改缺少完整差异')
        for path, change in changes.items():
            if not isinstance(path, str) or not isinstance(change, dict):
                raise ValueError('旧版差异格式无效')
            kind = change.get('type')
            if kind in ('add', 'delete'):
                if set(change) != {'type', 'content'} or not isinstance(change['content'], str):
                    raise ValueError('旧版文件内容不完整')
            elif kind == 'update':
                if (set(change) - {'type', 'unified_diff', 'move_path'}
                        or not isinstance(change.get('unified_diff'), str)):
                    raise ValueError('旧版文件差异不完整')
            else:
                raise ValueError('未支持的旧版修改类型')
        preview = '完整文件修改：\n' + visible(changes)
    else:
        raise ValueError('这是后台工具/身份验证请求，不是可手机代答的用户表单')
    preview += '\n原因：' + visible(params.get('reason') or '未提供')
    return preview, [option('仅此次允许', {'decision': 'approved'}),
                     option('拒绝本次', {'decision': {'denied': {'rejection': '用户拒绝本次请求'}}}),
                     option('取消本轮', {'decision': 'abort'})], {}
